import json
with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def get_packages(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg['resolvedVersion']
        result[pname] = pkgs
    return result

b = get_packages(baseline)
a = get_packages(after)
print('=== BASELINE ===')
for p, pkgs in sorted(b.items()):
    print(f'  {p}:')
    for pkg, ver in sorted(pkgs.items()):
        print(f'    {pkg} {ver}')
print()
print('=== AFTER CPM ===')
for p, pkgs in sorted(a.items()):
    print(f'  {p}:')
    for pkg, ver in sorted(pkgs.items()):
        print(f'    {pkg} {ver}')
print()
print('=== CHANGES ===')
for p in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(p, {})
    ap = a.get(p, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'N/A')
        av = ap.get(pkg, 'N/A')
        if bv != av:
            print(f'  {p}: {pkg} {bv} -> {av}')
